function commission(id){const def=board?.defs.find(d=>d.id===id),out=content.querySelector(`[data-board-feedback="${id}"]`);if(!def||!out||state.contracts.includes(id)||!def.needs.every(n=>state.solved.includes(n)))return;const inputs=[...content.querySelectorAll(`[data-board-input="${id}"]`)];if(inputs.some(i=>!Number.isFinite(parseNumber(i.value)))){out.textContent='Enter a number in every field.';return}const result=board.check(id,inputs.map(i=>parseNumber(i.value)));inputs.forEach((input,i)=>input.setAttribute('aria-invalid',String(!result.checks[i])));if(!result.ok){out.textContent='Not yet. Check: '+def.labels.filter((_,i)=>!result.checks[i]).join(', ')+'. Each part uses one of the three missions.';return}state.contracts.push(id);state.points+=CONTRACT_REWARD;save();render()}
/* Workshop arithmetic, kept free of the page so it can be tested directly.
   Every "is this zero?" test is relative to the size of the numbers entered, so a system or a
   matrix with very small or very large entries is judged the same way as one with ordinary entries. */
function toolResult(kind,v){
 const g=n=>{const r=Number(Number(n).toPrecision(5));return String(Object.is(r,-0)?0:r)};
 /* Two different values must not print as the same text: add digits until they differ. */
 const pair=(x,y)=>{if(x===y)return [g(x),g(y)];for(let d=5;d<=17;d++){const a=String(Number(x.toPrecision(d))),b=String(Number(y.toPrecision(d)));if(a!==b)return [a,b]}return [String(x),String(y)]};
 const big=list=>Math.max(...list.map(Math.abs));
 if(kind==='vector'){const[a,b,c,d]=v;return `A + B = (${g(a+c)}, ${g(b+d)}) · A · B = ${g(a*c+b*d)} · |A| = ${g(Math.hypot(a,b))} · |B| = ${g(Math.hypot(c,d))}`}
 if(kind==='matrix'){const[a,b,c,d,e,f]=v,det=a*d-b*c,scale=Math.hypot(a,b)*Math.hypot(c,d);if(scale===0||Math.abs(det)<=1e-12*scale)return 'det(A) = 0. The matrix is singular; there is no unique solution.';return `det(A) = ${g(det)} · x = ${g((e*d-b*f)/det)}, y = ${g((a*f-e*c)/det)}`}
 if(kind==='solve3'){const m=v.slice(0,9),b=v.slice(9),det3=x=>x[0]*(x[4]*x[8]-x[5]*x[7])-x[1]*(x[3]*x[8]-x[5]*x[6])+x[2]*(x[3]*x[7]-x[4]*x[6]),det=det3(m),scale=Math.hypot(m[0],m[1],m[2])*Math.hypot(m[3],m[4],m[5])*Math.hypot(m[6],m[7],m[8]);
  /* |det| equals the product of the row lengths times the volume of the unit rows, so this ratio
     measures how close the rows are to dependent, whatever their overall size. */
  if(scale===0||Math.abs(det)<=1e-12*scale)return 'det(A) = 0. The matrix is singular; there is no unique solution.';
  const col=k=>m.map((x,i)=>i%3===k?b[Math.floor(i/3)]:x);return `det(A) = ${g(det)} · x = ${g(det3(col(0))/det)}, y = ${g(det3(col(1))/det)}, z = ${g(det3(col(2))/det)}`}
 if(kind==='linefit'){const xs=[v[0],v[2],v[4]],ys=[v[1],v[3],v[5]],span=Math.max(...xs)-Math.min(...xs);
  /* A unique line needs at least two different x values; "different" is judged against their size. */
  if(span<=1e-12*big(xs))return 'All three x values are equal, so no unique line exists.';
  const x0=xs[0],dx=xs.map(x=>(x-x0)/span),md=(dx[0]+dx[1]+dx[2])/3,my=(ys[0]+ys[1]+ys[2])/3,sxx=dx.reduce((n,x)=>n+(x-md)**2,0),slope=dx.reduce((n,x,i)=>n+(x-md)*(ys[i]-my),0)/sxx/span,intercept=my-slope*(x0+md*span),sse=xs.reduce((n,x,i)=>n+(ys[i]-intercept-slope*x)**2,0);
  return `y = ${g(intercept)} + ${g(slope)}·x · sum of squared residuals = ${g(sse)}`}
 if(kind==='eigen'){const[a,b,c,d]=v,s=big(v),tr=a+d,det=a*d-b*c,head=`trace = ${g(tr)} · det = ${g(det)} · `;
  if(s===0)return head+'repeated eigenvalue 0; every nonzero vector is an eigenvector.';
  /* (a−d)²+4bc is the discriminant written so that nearly equal diagonal entries do not cancel. */
  const disc=(a-d)*(a-d)+4*b*c,tol=1e-24*s*s,tiny=1e-12*s;
  if(disc<-tol)return head+`complex eigenvalues ${g(tr/2)} ± ${g(Math.sqrt(-disc)/2)}i; no real eigenvectors.`;
  const vec=l=>Math.abs(b)>tiny?[b,l-a]:Math.abs(c)>tiny?[l-d,c]:Math.abs(l-a)<=Math.abs(l-d)?[1,0]:[0,1],show=l=>'('+vec(l).map(g).join(', ')+')';
  if(disc<=tol){const l=tr/2;return Math.abs(b)<=tiny&&Math.abs(c)<=tiny?head+`repeated eigenvalue ${g(l)}; every nonzero vector is an eigenvector.`:head+`repeated eigenvalue ${g(l)} with only one independent eigenvector ${show(l)} (defective).`}
  const r=Math.sqrt(disc),l1=(tr-r)/2,l2=(tr+r)/2,[t1,t2]=pair(l1,l2);return head+`λ₁ = ${t1} with eigenvector ${show(l1)} · λ₂ = ${t2} with eigenvector ${show(l2)}`}
 const[a,b,c,d]=v,den=c*c+d*d;if(!den)return 'Projection onto the zero vector is undefined.';const k=(a*c+b*d)/den;return `Projection = (${g(k*c)}, ${g(k*d)}) · Perpendicular component = (${g(a-k*c)}, ${g(b-k*d)})`}
function calculate(form){const inputs=[...form.querySelectorAll('input')],out=form.querySelector('.result');if(inputs.some(i=>!Number.isFinite(parseNumber(i.value)))){out.textContent='Enter a number in each field. Fractions such as 3/4 work.';return}out.textContent=toolResult(form.dataset.calc,inputs.map(i=>parseNumber(i.value)))}
