  function showGuide(force=false){assisted=true;let box=$('#guided'),steps=q.guidance||[];if(!force&&box.innerHTML){box.querySelector('h3')?.focus();return}if(!steps.length){box.innerHTML='<div class="hint">Review the lesson and use the hints to break this problem into smaller steps.</div>';return}if(guidedIndex>=steps.length){box.innerHTML='<div class="hint"><b>GUIDED STEPS COMPLETE</b><br>Nice work. Use your results to answer the main objective above.</div>';return}let g=steps[guidedIndex];box.innerHTML=`<div class="guided-panel"><h3 tabindex="-1">GUIDED STEP ${guidedIndex+1} / ${steps.length}</h3><p>${esc(g.prompt)}</p><div class="answer-grid">${g.answer.map((_,i)=>`<div><label for="guided-${i}">${esc(g.labels[i]||'ANSWER '+(i+1))}</label><input id="guided-${i}" type="text" inputmode="decimal" autocomplete="off"></div>`).join('')}</div><div class="modal-actions"><button class="secondary" id="check-guided">Check this step →</button><button class="secondary" id="explain-guided">Let’s work through this step</button></div><div class="guided-feedback" aria-live="polite"></div></div>`;box.querySelector('h3').focus();let stepWrong=0;const explain=()=>{let f=box.querySelector('.guided-feedback');f.innerHTML=`<strong>Let’s work through it.</strong> ${esc(g.explanation)} <button class="secondary guided-next">Continue to ${guidedIndex===steps.length-1?'the objective':'next step'} →</button>`;f.querySelector('button').onclick=()=>{guidedIndex++;showGuide(true)}};$('#explain-guided').onclick=explain;$('#check-guided').onclick=()=>{let inputs=[...box.querySelectorAll('input')],f=box.querySelector('.guided-feedback');if(inputs.some(x=>!Number.isFinite(parseNumber(x.value)))){f.textContent='Enter a number in each field first.';return}if(inputs.every((x,i)=>Math.abs(parseNumber(x.value)-Number(g.answer[i]))<=(q.tolerance??.01))){f.innerHTML=`<strong>That’s it.</strong> ${esc(g.explanation)}`;$('#check-guided').textContent=guidedIndex===steps.length-1?'Finish guidance →':'Next step →';$('#check-guided').onclick=()=>{guidedIndex++;showGuide(true)}}else {stepWrong++;if(stepWrong>=2)explain();else f.textContent='You’re learning. Try this step again, or choose “Let’s work through this step” for an explanation.'}}}
