  function assessAnswer(){let ins=[...dc.querySelectorAll('#mission-stage > .mission-panel > .answer-grid input')],feedback=dc.querySelector('.feedback');if(ins.some(i=>!Number.isFinite(parseNumber(i.value)))){feedback.textContent='Enter a number in every field.';return}let checks=ins.map((input,i)=>Math.abs(parseNumber(input.value)-Number(q.answer[i]))<=(q.tolerance??.01));ins.forEach((input,i)=>{let status=$(`#answer-status-${i}`);status.textContent=checks[i]?'✓ This component is right':'Try this component again';status.className='field-status '+(checks[i]?'right':'retry');input.setAttribute('aria-invalid',String(!checks[i]))});if(checks.some(x=>!x)){wrong++;assisted=true;recordError(q.id);showPitfalls();feedback.textContent=wrong===1?`Good start. ${q.hints[0]||q.teaching?.pitfalls?.[0]||'Review the worked example and try again.'}`:'Let’s break it down together. Use the guided step below, then return to your answer.';if(wrong>=2)showGuide();return}if(!solved(q)&&!revealed)award();else if(revealed&&!solved(q)&&generated)feedback.textContent='Correct. This attempt is practice because the solution was revealed. Reopen the mission: it will have new numbers and the full reward.';else if(revealed&&!solved(q)){feedback.textContent='Correct. Because the solution was revealed, the reward needs one check with fresh numbers.';variantGate()}else feedback.textContent='Correct! Practice complete.';if(REALM.id==='la'&&q.id==='q29'&&solved(q)&&contracts?.challengeHTML){feedback.insertAdjacentHTML('beforeend',contracts.challengeHTML());contracts.mountChallenge(feedback,{solvedIds:state.solved,requireUnlock:true})}}
